// components/Orb.tsx
"use client";

import * as React from "react";

const isVideoUrl = (url: string) => {
  return /\.(mp4|webm|ogg|mov)$/i.test(url)
}

type OrbProps = {
  src?: string;
  size?: number; // px

  // Mode A: numeric controls (used when raw styles not provided)
  hueDeg?: number;      // e.g. 149
  saturate?: number;    // e.g. 1.2 for 120%
  rotateDeg?: number;   // e.g. 149

  // Mode B: raw CSS strings (take precedence over numeric)
  filter?: string;      // e.g. "hue-rotate(101deg) saturate(120%)"
  transform?: string;   // e.g. "rotate(101deg)"

  // Common image props
  objectFit?: React.CSSProperties["objectFit"];             // default "cover"
  objectPosition?: React.CSSProperties["objectPosition"];   // default "center center"

  // NEW: allow arbitrary style overrides for wrapper and image
  wrapperStyle?: React.CSSProperties;
  imgStyle?: React.CSSProperties;

  className?: string;
  imgClassName?: string;
};

export function Orb({
  src = "/themes/orb-5.webp",
  size = 128,

  // numeric defaults
  hueDeg = 149,
  saturate = 1.2,
  rotateDeg = 149,

  // raw string overrides
  filter,
  transform,

  objectFit = "cover",
  objectPosition = "center center",

  // NEW style overrides
  wrapperStyle,
  imgStyle,

  className,
  imgClassName,
}: OrbProps) {
  // base wrapper style
  const baseWrapperStyle: React.CSSProperties = { width: size, height: size };

  // base image style (numeric or raw)
  const baseImgStyle: React.CSSProperties = {
    filter: filter ?? `hue-rotate(${hueDeg}deg) saturate(${saturate})`,
    transform: transform ?? `rotate(${rotateDeg}deg)`,
    objectFit,
    objectPosition,
  };

  // Merge order: base → overrides (overrides win)
  const mergedWrapperStyle = { ...baseWrapperStyle, ...(wrapperStyle ?? {}) };
  const mergedImgStyle = { ...baseImgStyle, ...(imgStyle ?? {}) };

  const isVideo = isVideoUrl(src)

  return (
    <div
      className={`relative overflow-hidden rounded-full ${className ?? ""}`}
      style={mergedWrapperStyle}
      aria-hidden
    >
      {isVideo ? (
        <video
          src={src}
          autoPlay
          loop
          muted
          playsInline
          className={`h-full w-full ${imgClassName ?? ""}`}
          style={mergedImgStyle}
        />
      ) : (
        <img
          src={src}
          alt=""
          draggable={false}
          className={`h-full w-full ${imgClassName ?? ""}`}
          style={mergedImgStyle}
        />
      )}
    </div>
  );
}

"use client"

import {
  createContext,
  ReactNode,
  useContext,
  useEffect,
  useState,
} from "react"

const DEFAULT_THEME = "default"
const THEME_STORAGE_KEY = "active-theme"

type ThemeContextType = {
  activeTheme: string
  setActiveTheme: (theme: string) => void
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined)

export function ActiveThemeProvider({
  children,
  initialTheme,
}: {
  children: ReactNode
  initialTheme?: string
}) {
  const [activeTheme, setActiveThemeState] = useState<string>(() => {
    // Try to read from localStorage first
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem(THEME_STORAGE_KEY)
      if (stored) {
        return stored
      }
    }
    return initialTheme || DEFAULT_THEME
  })

  const [mounted, setMounted] = useState(false)
  // Theme is considered loaded once we've mounted and applied the initial theme
  const themeLoaded = mounted

  useEffect(() => {
    setMounted(true)
  }, [])

  useEffect(() => {
    if (!mounted) return

    // Ensure theme is applied immediately on mount
    Array.from(document.body.classList)
      .filter((className) => className.startsWith("theme-"))
      .forEach((className) => {
        document.body.classList.remove(className)
      })
    document.body.classList.add(`theme-${activeTheme}`)
    if (activeTheme.endsWith("-scaled")) {
      document.body.classList.add("theme-scaled")
    }

    // Remove loading state and show content
    document.body.classList.remove("theme-loading")

    // Save to localStorage
    localStorage.setItem(THEME_STORAGE_KEY, activeTheme)
  }, [activeTheme, mounted])

  const setActiveTheme = (theme: string) => {
    setActiveThemeState(theme)
  }

  // Don't render children until theme is loaded to prevent FOUC
  if (!themeLoaded) {
    return null
  }

  return (
    <ThemeContext.Provider value={{ activeTheme, setActiveTheme }}>
      {children}
    </ThemeContext.Provider>
  )
}

export function useThemeConfig() {
  const context = useContext(ThemeContext)
  if (context === undefined) {
    throw new Error("useThemeConfig must be used within an ActiveThemeProvider")
  }
  return context
}

